// Relay a Claude sign-in link from ai-deck to the owner's Telegram.
// /webhook/ is public (homepage nginx skips basic auth for Telegram), so a
// stranger could otherwise make the Secretary Bot send a fake "sign in" link:
// a ready-made phishing channel. Caller must present X-Desk-Token, and the URL
// must pass the same allowlist as ai-deck/login_link.py + ui/app.js.
// Rejections return ok:false (answered 401/400) instead of throwing, so
// hammering the URL cannot spam the Error Alerter.
const { createHash, timingSafeEqual } = require('crypto');
const item = $input.first().json;
const b = item.body || {};
const h = item.headers || {};
const reject = (code, reason) => [{ json: { ok: false, code, reason } }];
const digest = (s) => createHash('sha256').update(String(s)).digest();

const want = $env.DESK_LOGIN_TOKEN;
if (!want) return reject(401, 'desk login token is not configured');   // fail closed
if (!timingSafeEqual(digest(h['x-desk-token'] || ''), digest(want))) return reject(401, 'bad token');

const raw = String(b.url ?? '');
if (raw.length > 2048) return reject(400, 'url too long');
let url;
try { url = new URL(raw); } catch (_) { return reject(400, 'not a url'); }
const hosts = ['claude.com', 'claude.ai', 'console.anthropic.com', 'platform.claude.com'];
const shortForm = /^\?z-[A-Za-z0-9_-]{16,}$/.test(url.search);
const longForm = ['client_id', 'state', 'code_challenge'].every(k => url.searchParams.has(k));
if (url.protocol !== 'https:' || url.username || url.password || url.port
    || !hosts.includes(url.hostname) || !/^(\/[a-z]+)?\/oauth\/authorize$/.test(url.pathname)
    || !(shortForm || longForm)) {
  return reject(400, 'not a Claude sign-in link');
}

const desk = String(b.desk ?? '');
if (!/^[a-z0-9_-]{1,32}$/.test(desk)) return reject(400, 'bad desk');

return [{ json: { ok: true, desk, url: raw } }];
